head.script:
scwin.onpageload = function() {
    var jsonData = [{
            col1: "111111",
            col2: "222222",
            col3: "333333",
            col4: "444444",
            col5: "444444",
            col6: "444444",
            col7: "444444"
        }, {
            col1: "111111",
            col2: "222222",
            col3: "333333",
            col4: "444444",
            col5: "444444",
            col6: "444444",
            col7: "444444"
        }, {
            col1: "111111",
            col2: "222222",
            col3: "333333",
            col4: "444444",
            col5: "444444",
            col6: "444444",
            col7: "444444"
        }
        //			,{col1:"111111",col2:"222222",col3:"333333",col4:"444444",col5:"444444",col6:"444444",col7:"444444"}
        //			,{col1:"111111",col2:"222222",col3:"333333",col4:"444444",col5:"444444",col6:"444444",col7:"444444"}
        //			,{col1:"111111",col2:"222222",col3:"333333",col4:"444444",col5:"444444",col6:"444444",col7:"444444"}
        //			,{col1:"111111",col2:"222222",col3:"333333",col4:"444444",col5:"444444",col6:"444444",col7:"444444"}
        //			,{col1:"111111",col2:"222222",col3:"333333",col4:"444444",col5:"444444",col6:"444444",col7:"444444"}
        //			,{col1:"111111",col2:"222222",col3:"333333",col4:"444444",col5:"444444",col6:"444444",col7:"444444"}
        //			,{col1:"111111",col2:"222222",col3:"333333",col4:"444444",col5:"444444",col6:"444444",col7:"444444"}
        //			,{col1:"111111",col2:"222222",col3:"333333",col4:"444444",col5:"444444",col6:"444444",col7:"444444"}
    ];
    dataList1.setJSON(jsonData);
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    dataList1.insertRow(dataList1.getTotalRow());
};
scwin.trigger2_onclick = function(e) {
    dataList1.insertJSON(dataList1.getTotalRow(), [{
        col1: "111111",
        col2: "222222",
        col3: "333333",
        col4: "444444",
        col5: "444444",
        col6: "444444",
        col7: "444444"
    }]);
};
scwin.trigger3_onclick = function(e) {
    dataList1.setRowJSON(dataList1.getTotalRow(), {
        col1: "111111",
        col2: "222222",
        col3: "333333",
        col4: "444444",
        col5: "444444",
        col6: "444444",
        col7: "444444"
    }, false);
};
scwin.trigger4_onclick = function(e) {
    gridView1.setColumnVisible(1, false);
    gridView1.setColumnVisible(3, false);
};
scwin.trigger5_onclick = function(e) {
    //로그 에러 발생 확인 안됨
    gridView1.setColumnOrder(["col1", "col3", "col5", "col6", "col7"]);
};

scwin.checkVal1 = function(){
	return WebSquare.wUnit.getJq('#gridView1_cell_3_1').height() == 0;
};
scwin.checkVal2 = function(){
	return WebSquare.wUnit.getJq('#gridView1_cell_3_3').height() == 0;
};

scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
